import java.util.Scanner;

public class JavaApplication1 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line1 = scanner.nextLine();
        String line2 = scanner.nextLine();
        String combined = line2.replaceAll("_+", " ").trim();
        StringBuilder insideParentheses = new StringBuilder();
        int flag = 0;
        for (char c : combined.toCharArray()) {
            if (c == '(') {
                flag = 1;
            } else if (c == ')') {
                insideParentheses.append(' ');
                flag = 0;
            } else if (flag == 1) {
                insideParentheses.append(c);
            }
        }
        String s = line2;
        int index;
        while ((index = s.indexOf('(')) != -1) {
            int closeIndex = s.indexOf(')', index);
            if (closeIndex == -1) break;
            s = s.substring(0, index) + " " + s.substring(closeIndex + 1);
        }
        s = s.replaceAll(" +", " ").trim();
        String ss = insideParentheses.toString().replaceAll(" +", " ").trim();
        String[] outWords = s.split(" ");
        String[] inWords = ss.split(" ");
        int maxLength = 0;
        for (String word : outWords) {
            if (word.length() > maxLength) {
                maxLength = word.length();
            }
        }
        if (!ss.isEmpty()) {
            System.out.println(maxLength + " " + inWords.length);
        } else {
            System.out.println(maxLength + " 0");
        }
    }
}
